INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('0d817823-335a-44e2-b7c7-13ba97421d5a', 'e80c9e4e-8509-492d-9252-a663b0101c4b', 'assistant', '**Varsayım:** Kullanıcı 10 adet THYAO hissesini piyasa emriyle TR‑DEMO‑0001 hesabından satın almak istiyor.  

**İşlem Önerisi**  

| Özellik | Değer |
|---|---|
