INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('037e20ff-da6a-4d21-ba63-ff26ef80e471', '0646ff42-a915-41a6-99f9-b1ffdd261bd0', 'assistant', 'Para ihtiyacınızı anlıyorum. Bu platform üzerinden doğrudan para temini sağlanamıyor. Finansal ihtiyaçlarınızı planlamak, bütçe oluşturmak ya da kredi seçeneklerini anlamak konusunda bilgi verebilirim. Hangi konuda yardımcı olmamı istersiniz?', '{"target_agent": "TRANSACTION_AGENT", "primary_intent": "TRANSACTION_REQUEST", "compliance_verdict": "PASS"}', '2026-08-21T06:01:09.850295+00:00') ON CONFLICT DO NOTHING;
