INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('94216ca1-3583-4530-bf97-7512fd6cd78a', '0672792b-edd3-461a-8548-1ee30cae02a7', 'assistant', '**İşlem Önerisi**

- İşlem tipi: Alım (BUY)
